package dev.shadw.olympia.mobs;

import net.minecraft.client.renderer.entity.EntityRendererProvider;
import net.minecraft.client.renderer.entity.MobRenderer;
import net.minecraft.resources.ResourceLocation;

/** Renders the Minotaur with its own model and texture. Generated by shadw-mod mob. */
public class MinotaurRenderer extends MobRenderer<Minotaur, MinotaurModel.State, MinotaurModel> {
	private static final ResourceLocation TEXTURE = ResourceLocation.fromNamespaceAndPath("olympia", "textures/entity/minotaur.png");

	public MinotaurRenderer(EntityRendererProvider.Context context) {
		super(context, new MinotaurModel(context.bakeLayer(MinotaurModel.LAYER)), 0.9F);
	}

	@Override
	public MinotaurModel.State createRenderState() {
		return new MinotaurModel.State();
	}

	@Override
	public void extractRenderState(Minotaur entity, MinotaurModel.State state, float partialTick) {
		super.extractRenderState(entity, state, partialTick);
		state.attackTime = entity.getAttackAnim(partialTick);
	}

	@Override
	public ResourceLocation getTextureLocation(MinotaurModel.State state) {
		return TEXTURE;
	}
}
